`REFERENCE MATERIAL

The following material is the authoritative source for this conversation.

If any previous assistant response contradicts this material,
the previous response is WRONG.

Always answer using the reference material below.`
            },
            ...adhocParts,
            ...cacheableParts
        ]
    });

}

/*
 * 2. Previous conversation
 */
const MAX_HISTORY = 30;

const previousConversation =
    (session?.conversation || [])
        .slice(-MAX_HISTORY);

for (const m of previousConversation) {

    contents.push({
        role: m.role,
        parts: [
            {
                text: m.text
            }
        ]
    });

}

/*
 * 3. Latest user messages
 */
const latestMessage = body.messages?.at(-1);

if (latestMessage) {

    contents.push({
        role: latestMessage.role,
        parts: [
            {
                text: latestMessage.text
            }
        ]
    });

}

const geminiBody = {
  contents,
  system_instruction: {
    parts: [
      {
        text:
`${body.systemPrompt}

Grounding rules:

• The attached documents are the authoritative source.

• If previous assistant responses contradict the attached documents, correct yourself immediately.

• Never repeat an incorrect previous answer merely for consistency.

• Prefer the attached documents over conversation history.

• If multiple documents exist, answer primarily from the PRIMARY DOCUMENT unless the user explicitly asks to compare them.

• If information is absent from the documents, clearly say so instead of guessing.
`
      }
    ]
  },
  generationConfig: {
    temperature: 0.7,
    maxOutputTokens: 49152
  }
};

return [{
  json: {
    geminiBody,
    sessionId: body.chatId,
    documentHash
  }
}];

