if (reason === 'SAFETY') return { json: { result: '[Blocked] The AI safety filters prevented processing this content.' } };

const text = (candidate?.content?.parts || []).filter(p => p.text).map(p => p.text).join('\n').trim();
if (!text) {
  if (status === 200) return { json: { failed: true, result: '[No reply] The tutor returned an empty response. Please resend your message.' } };
  throw new Error(`Tutor Gemini failed: HTTP ${status} ${response.body?.error?.message || ''}`);
}

