function extractDoi(url) {
  const m = url.match(/\/(10\.\d{4,9}\/[^\s?#]+)/);
  return m ? m[1].replace(/\/+$/, '') : null;
}

function isJsShell(rawHtml) {
  if (!rawHtml || rawHtml.length < 500) return true;
  const lower = rawHtml.toLowerCase();
  const signals = ['enable javascript', 'just a moment', 'cf-browser-verification', 'challenge-platform', '_cf_chl', 'checking your browser', 'ray id'];
  if (signals.filter(s => lower.includes(s)).length >= 2) return true;
  const textOnly = rawHtml.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
  return textOnly.length < 200;
}

async function doiFallback(doi) {
  let text = '';
  let note = '';

  const [crResult, upResult] = await Promise.allSettled([
    helpers.httpRequest({
      method: 'GET',
      url: `https://api.crossref.org/works/${encodeURIComponent(doi)}`,
      headers: { 'User-Agent': 'StudentToolsHub/1.0 (mailto:jay-leigh.v@conversionscience.co.za)' },
      json: true,
      timeout: 8000,
    }),
    helpers.httpRequest({
      method: 'GET',
