const MAX_ATTEMPTS = 4;
const FALLBACK_FROM_ATTEMPT = 3;
const FALLBACK_MODEL = 'gemini-2.5-flash-lite';
const res = $input.first().json;
const status = res.statusCode;
const candidate = res.body?.candidates?.[0];
const hasText = !!candidate?.content?.parts?.some(p => p.text);
const reason = candidate?.finishReason || '';
const blocked = ['SAFETY', 'RECITATION', 'PROHIBITED_CONTENT', 'BLOCKLIST', 'SPII'].includes(reason) || !!res.body?.promptFeedback?.blockReason;
const isRateLimited = status === 429;
const isServerError = [500, 503, 504].includes(status);
const isEmptyReply = status === 200 && !hasText && !blocked;
const attempt = $runIndex + 1;
const retry = (isRateLimited || isServerError || isEmptyReply) && attempt < MAX_ATTEMPTS;

let waitSeconds = 0;
if (retry) {
  if (isRateLimited && attempt + 1 === FALLBACK_FROM_ATTEMPT) {
    waitSeconds = 3;
  } else if (isRateLimited) {
    const hinted = parseFloat((res.body?.error?.message || '').match(/retry in ([\d.]+)s/i)?.[1]);
    waitSeconds = (Number.isFinite(hinted) ? Math.ceil(hinted) + 5 : 35) + Math.floor(Math.random() * 5);
  } else {
    waitSeconds = 5 * attempt;
  }
  waitSeconds = Math.min(waitSeconds, 60);
}

return [{ json: { ...res, geminiBody: $('Prep — Tutor').first().json.geminiBody, retry, waitSeconds, attempt, model: attempt + 1 >= FALLBACK_FROM_ATTEMPT ? FALLBACK_MODEL : undefined } }];

const body = $input.first().json.body;
const startPage = Number(body.startPage);
const endPage = Number(body.endPage);
const MAX_PAGES_PER_REQUEST = 5;

if (!/^[0-9a-f]{64}$/.test(body.contentHash || '')) throw new Error('OCR: missing or invalid contentHash');
if (!(startPage >= 1) || !(endPage >= startPage) || endPage - startPage + 1 > MAX_PAGES_PER_REQUEST) {
  throw new Error(`OCR: invalid page range ${body.startPage}-${body.endPage}`);
}

return [{ json: {
  contentHash: body.contentHash,
  startPage,
  endPage,
  pdfBase64: body.pdfBase64 || null,
  cacheKey: `ocr:${body.contentHash}:${startPage}-${endPage}`
} }];

const prep = $('OCR — Prep').first().json;
const cached = $input.first().json.result;
const { startPage, endPage } = prep;

if (cached) {
  return [{ json: { done: true, response: { cached: true, startPage, endPage, pages: JSON.parse(cached).pages } } }];
}
if (!prep.pdfBase64) {
  return [{ json: { done: true, response: { cached: false, missing: true, startPage, endPage, pages: [] } } }];
}

const pageCount = endPage - startPage + 1;
return [{ json: {
  done: false,
  visionBody: {
    requests: [{
      inputConfig: { content: prep.pdfBase64, mimeType: 'application/pdf' },
      features: [{ type: 'DOCUMENT_TEXT_DETECTION' }],
      pages: Array.from({ length: pageCount }, (_, i) => i + 1)
    }]
  }
} }];

const prep = $('OCR — Prep').first().json;
const pageResponses = $input.first().json.responses?.[0]?.responses || [];
const { startPage, endPage } = prep;

const rawPages = [];
for (let page = startPage; page <= endPage; page++) {
  const result = pageResponses[page - startPage] || {};
  if (result.error) throw new Error(`OCR: Vision failed on scan page ${page}: ${result.error.message}`);
  rawPages.push({ page, lines: (result.fullTextAnnotation?.text || '').split('\n') });
}

// Running headers repeat across pages; page numbers sit on their own line.
const normalize = line => line.trim().toLowerCase().replace(/\s+/g, ' ');
const lineCounts = {};
for (const { lines } of rawPages) for (const line of lines) {
  const key = normalize(line);
  if (key) lineCounts[key] = (lineCounts[key] || 0) + 1;
}
const isPageNumber = line => /^([0-9]{1,4}|[ivxlc]{1,7})$/i.test(line.trim());
const minHeaderRepeats = Math.max(2, Math.ceil(rawPages.length * 0.6));
const isRunningHeader = line => {
  const key = normalize(line);
  return lineCounts[key] >= minHeaderRepeats && key.split(' ').length >= 4 && key.length < 100;
};

const pages = rawPages.map(({ page, lines }) => ({
  page,
  text: lines.filter(line => !isPageNumber(line) && !isRunningHeader(line)).join('\n').replace(/\n{3,}/g, '\n\n').trim()
}));

return [{ json: {
  cacheKey: prep.cacheKey,
  cacheValue: JSON.stringify({ pages }),
  response: { cached: false, startPage, endPage, pages }
} }];
